        int steps = 0;
        for (int factor = 2; factor * factor <= n; ++factor) {
            while (n % factor == 0) {
                steps += factor;
                n /= factor;
            }
        }
        if (n > 1) {
            steps += n;
        }
        return steps;
    }
};
