#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    vector<string> ambiguousCoordinates(string s) {
        auto representations = [](const string& digits) {
            vector<string> result;
            int n = digits.size();

            if (n == 1 || digits[0] != '0') {
                result.push_back(digits);
            }

            if (digits.back() == '0') {
                return result;
            }

            for (int i = 1; i < n; ++i) {
                if (i > 1 && digits[0] == '0') {
                    break;
                }
                result.push_back(digits.substr(0, i) + "." + digits.substr(i));
            }

            return result;
        };

        string digits = s.substr(1, s.size() - 2);
        vector<string> answer;

        for (int split = 1; split < static_cast<int>(digits.size()); ++split) {
            vector<string> left = representations(digits.substr(0, split));
            vector<string> right = representations(digits.substr(split));

            for (const string& x : left) {
                for (const string& y : right) {
                    answer.push_back("(" + x + ", " + y + ")");
                }
            }
        }

        return answer;
    }
};
