class Solution {
public:
    int countVowelPermutation(int n) {
        constexpr long long MOD = 1000000007;
        long long a = 1, e = 1, i = 1, o = 1, u = 1;

        for (int length = 2; length <= n; ++length) {
            long long nextA = (e + i + u) % MOD;
            long long nextE = (a + i) % MOD;
            long long nextI = (e + o) % MOD;
            long long nextO = i;
            long long nextU = (i + o) % MOD;

            a = nextA;
            e = nextE;
            i = nextI;
            o = nextO;
            u = nextU;
        }

        return static_cast<int>((a + e + i + o + u) % MOD);
    }
};
