class Solution {
public:
    int clumsy(int n) {
        int result = 0;
        int term = n;
        int sign = 1;
        int operation = 0;

        for (int value = n - 1; value >= 1; --value) {
            if (operation == 0) {
                term *= value;
            } else if (operation == 1) {
                term /= value;
            } else {
                result += sign * term;
                term = value;
                sign = (operation == 2) ? 1 : -1;
            }

            operation = (operation + 1) % 4;
        }

        return result + sign * term;
    }
};
