using namespace std;

class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        if (stones[1] != 1) return false;

        // reachable[i][k]: stone i can be reached with a jump of length k.
        vector<vector<unsigned char>> reachable(
            n, vector<unsigned char>(n + 1, 0));
        reachable[0][0] = 1;

        for (int i = 1; i < n; ++i) {
            for (int j = i - 1; j >= 0; --j) {
                int k = stones[i] - stones[j];

                // From stone j, the next jump cannot exceed j + 1.
                if (k > j + 1) break;

                if (reachable[j][k - 1] ||
                    reachable[j][k] ||
                    reachable[j][k + 1]) {
                    reachable[i][k] = 1;
                    if (i == n - 1) return true;
                }
            }
        }

        return false;
    }
};
