class Solution {
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        int answer = 1;

        for (int i = 0; i < n; ++i) {
            if (answer >= n - i) break;

            unordered_map<long long, int> counts;
            counts.reserve(n - i);

            for (int j = i + 1; j < n; ++j) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int g = gcd(abs(dx), abs(dy));
                dx /= g;
                dy /= g;

                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                long long key = (static_cast<long long>(dx) << 32)
                              | static_cast<unsigned int>(dy);

                answer = max(answer, ++counts[key] + 1);
            }
        }

        return answer;
    }
