class Solution {
public:
    int countMaxOrSubsets(vector<int>& nums) {
        int target = 0;
        for (int num : nums) {
            target |= num;
        }

        int n = static_cast<int>(nums.size());

        auto dfs = [&](auto&& self, int index, int currentOr) -> int {
            if (currentOr == target) {
                return 1 << (n - index);
