        --size;
        int result = values[size] + pending[size];
        if (size > 0) {
            pending[size - 1] += pending[size];
        }
        pending[size] = 0;
        return result;
    }

    void increment(int k, int val) {
        int count = std::min(k, size);
        if (count > 0) {
