using namespace std;

class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int left = 0;
        int total = 0;
        int answer = 0;

        auto stepsNeeded = [&](int l, int r) {
            int leftPos = fruits[l][0];
            int rightPos = fruits[r][0];
            return rightPos - leftPos +
                   min(abs(startPos - leftPos), abs(startPos - rightPos));
        };

        for (int right = 0; right < static_cast<int>(fruits.size()); ++right) {
            total += fruits[right][1];

            while (left <= right && stepsNeeded(left, right) > k) {
                total -= fruits[left][1];
                ++left;
            }

            answer = max(answer, total);
        }

        return answer;
    }
};
