    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();

        vector<vector<int>> row(m, vector<int>(n + 1));
        vector<vector<int>> col(m + 1, vector<int>(n));
        vector<vector<int>> diag(m + 1, vector<int>(n + 1));
        vector<vector<int>> anti(m + 1, vector<int>(n + 1));

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                row[i][j + 1] = row[i][j] + grid[i][j];
                col[i + 1][j] = col[i][j] + grid[i][j];
                diag[i + 1][j + 1] = diag[i][j] + grid[i][j];
                anti[i + 1][j] = anti[i][j + 1] + grid[i][j];
            }
        }

        for (int k = min(m, n); k >= 2; --k) {
            for (int r = 0; r + k <= m; ++r) {
                for (int c = 0; c + k <= n; ++c) {
                    int target = row[r][c + k] - row[r][c];

                    if (diag[r + k][c + k] - diag[r][c] != target ||
                        anti[r + k][c] - anti[r][c + k] != target) {
                        continue;
                    }

                    bool valid = true;
                    for (int offset = 0; offset < k; ++offset) {
                        if (row[r + offset][c + k] - row[r + offset][c] != target ||
                            col[r + k][c + offset] - col[r][c + offset] != target) {
                            valid = false;
                            break;
                        }
                    }

                    if (valid) {
                        return k;
                    }
                }
            }
        }

        return 1;
    }
};
