#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size();
        int n = seats[0].size();
        int limit = 1 << n;

        vector<int> count(limit, 0);
        vector<int> validMasks;
        for (int mask = 0; mask < limit; ++mask) {
            count[mask] = __builtin_popcount(static_cast<unsigned>(mask));
            if ((mask & (mask << 1)) == 0) {
                validMasks.push_back(mask);
            }
        }

        vector<int> dp(limit, -1);
        dp[0] = 0;

        for (int row = 0; row < m; ++row) {
            int available = 0;
            for (int col = 0; col < n; ++col) {
                if (seats[row][col] == '.') {
                    available |= 1 << col;
                }
            }

            vector<int> next(limit, -1);
            for (int mask : validMasks) {
                if ((mask & available) != mask) {
                    continue;
                }

                for (int previous : validMasks) {
                    if (dp[previous] == -1) {
                        continue;
                    }
                    if ((mask & (previous << 1)) ||
                        (mask & (previous >> 1))) {
                        continue;
                    }

                    next[mask] = max(next[mask], dp[previous] + count[mask]);
                }
            }
            dp.swap(next);
        }

        return *max_element(dp.begin(), dp.end());
    }
};
