using namespace std;

class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        sort(flowers.begin(), flowers.end());

        int n = flowers.size();
        int incomplete = lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin();

        vector<long long> prefix(incomplete + 1, 0);
        for (int i = 0; i < incomplete; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long long answer = 0;
        long long completionCost = 0;

        for (int remaining = incomplete; remaining >= 0; --remaining) {
            if (completionCost > newFlowers) {
                break;
            }

            long long beauty = 1LL * (n - remaining) * full;

            if (remaining > 0) {
                long long budget = newFlowers - completionCost;
                int low = 1, high = remaining;

                while (low < high) {
                    int mid = low + (high - low + 1) / 2;
                    long long cost = 1LL * flowers[mid - 1] * mid - prefix[mid];

                    if (cost <= budget) {
                        low = mid;
                    } else {
                        high = mid - 1;
                    }
                }

                long long minimum = min(
                    1LL * target - 1,
                    (budget + prefix[low]) / low
                );
                beauty += minimum * partial;
            }

            answer = max(answer, beauty);

            if (remaining > 0) {
                completionCost += target - flowers[remaining - 1];
            }
        }

        return answer;
    }
};
