class Solution {
public:
    int minCost(int maxTime, vector<vector<int>>& edges, vector<int>& passingFees) {
        int n = passingFees.size();
        const int INF = 1000000000;

        // dp[t][u]: minimum cost to reach city u in exactly t minutes.
        vector<vector<int>> dp(maxTime + 1, vector<int>(n, INF));
        dp[0][0] = passingFees[0];

        for (int t = 1; t <= maxTime; ++t) {
            for (const auto& edge : edges) {
                int u = edge[0], v = edge[1], travelTime = edge[2];
                if (travelTime > t) continue;

                int previousTime = t - travelTime;
                if (dp[previousTime][u] != INF) {
                    dp[t][v] = min(dp[t][v],
                                   dp[previousTime][u] + passingFees[v]);
                }
                if (dp[previousTime][v] != INF) {
                    dp[t][u] = min(dp[t][u],
                                   dp[previousTime][v] + passingFees[u]);
                }
            }
        }

        int answer = INF;
        for (int t = 0; t <= maxTime; ++t) {
            answer = min(answer, dp[t][n - 1]);
        }
        return answer == INF ? -1 : answer;
    }
};
