class Solution {
public:
    int minDays(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        const int dr[4] = {-1, 1, 0, 0};
        const int dc[4] = {0, 0, -1, 1};

        auto countIslands = [&]() -> int {
            vector<vector<bool>> visited(m, vector<bool>(n, false));
            int islands = 0;

            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] == 0 || visited[r][c]) continue;
                    if (++islands > 1) return islands;

                    vector<int> stack = {r * n + c};
                    visited[r][c] = true;

                    while (!stack.empty()) {
                        int cell = stack.back();
                        stack.pop_back();
                        int row = cell / n, col = cell % n;

                        for (int d = 0; d < 4; ++d) {
                            int nr = row + dr[d];
                            int nc = col + dc[d];

