        vector<int> dp(totalMasks, -1);
        dp[0] = 0;

        for (int mask = 0; mask < totalMasks - 1; ++mask) {
            int student = __builtin_popcount(static_cast<unsigned>(mask));
            for (int mentor = 0; mentor < m; ++mentor) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = max(dp[nextMask],
                                       dp[mask] + score[student][mentor]);
                }
            }
        }

        return dp[totalMasks - 1];
    }
