using namespace std;

class Solution {
public:
    int daysBetweenDates(string date1, string date2) {
        auto toDays = [](const string& date) {
            int year = stoi(date.substr(0, 4));
            int month = stoi(date.substr(5, 2));
            int day = stoi(date.substr(8, 2));

            const int daysBeforeMonth[] = {
                0, 31, 59, 90, 120, 151,
                181, 212, 243, 273, 304, 334
            };

            int previousYears = year - 1;
            int total = 365 * previousYears
                      + previousYears / 4
                      - previousYears / 100
                      + previousYears / 400
                      + daysBeforeMonth[month - 1]
                      + day;

            bool leapYear = year % 400 == 0 ||
                            (year % 4 == 0 && year % 100 != 0);

            if (month > 2 && leapYear) {
                ++total;
            }

            return total;
        };

        return abs(toDays(date1) - toDays(date2));
    }
};
