    int minDays(vector<int>& bloomDay, int m, int k) {
        if (1LL * m * k > static_cast<long long>(bloomDay.size())) {
            return -1;
        }

        int low = *min_element(bloomDay.begin(), bloomDay.end());
        int high = *max_element(bloomDay.begin(), bloomDay.end());

        auto canMake = [&](int day) {
            int bouquets = 0;
            int consecutive = 0;

            for (int bloom : bloomDay) {
                if (bloom > day) {
                    consecutive = 0;
                } else if (++consecutive == k) {
                    consecutive = 0;
                    if (++bouquets >= m) {
                        return true;
                    }
                }
            }
            return false;
        };

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canMake(mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }
