#include <vector>
#include <utility>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int totalMasks = 1 << n;

        // dp[mask] = {sessions used, time used in the last session}.
        vector<pair<int, int>> dp(totalMasks, {n + 1, 0});
        dp[0] = {1, 0};

        for (int mask = 0; mask < totalMasks; ++mask) {
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;

                auto next = dp[mask];
                if (next.second + tasks[i] <= sessionTime) {
                    next.second += tasks[i];
                } else {
                    ++next.first;
                    next.second = tasks[i];
                }

                int nextMask = mask | (1 << i);
                dp[nextMask] = min(dp[nextMask], next);
            }
        }

        return dp[totalMasks - 1].first;
    }
};
