class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int removeLeft = 0, removeRight = 0;
        for (char c : s) {
            if (c == '(') {
                ++removeLeft;
            } else if (c == ')') {
                if (removeLeft > 0) {
                    --removeLeft;
                } else {
                    ++removeRight;
                }
            }
        }

        int n = s.size();
        vector<int> suffixLeft(n + 1, 0), suffixRight(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            suffixLeft[i] = suffixLeft[i + 1] + (s[i] == '(');
            suffixRight[i] = suffixRight[i + 1] + (s[i] == ')');
        }

        unordered_set<string> answers;
        string current;
        current.reserve(n);

        function<void(int, int, int, int)> dfs =
            [&](int i, int balance, int left, int right) {
                if (left > suffixLeft[i] || right > suffixRight[i]) {
                    return;
                }
                if (balance > suffixRight[i] - right) {
                    return;
                }

                if (i == n) {
                    if (balance == 0 && left == 0 && right == 0) {
                        answers.insert(current);
                    }
                    return;
                }

                char c = s[i];
                if (c == '(') {
                    if (left > 0) {
                        dfs(i + 1, balance, left - 1, right);
                    }
                    current.push_back(c);
                    dfs(i + 1, balance + 1, left, right);
                    current.pop_back();
                } else if (c == ')') {
                    if (right > 0) {
                        dfs(i + 1, balance, left, right - 1);
                    }
                    if (balance > 0) {
                        current.push_back(c);
                        dfs(i + 1, balance - 1, left, right);
                        current.pop_back();
                    }
                } else {
                    current.push_back(c);
                    dfs(i + 1, balance, left, right);
                    current.pop_back();
                }
            };

        dfs(0, 0, removeLeft, removeRight);
        return vector<string>(answers.begin(), answers.end());
    }
