#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isScramble(string s1, string s2) {
        if (s1.size() != s2.size()) return false;
        int n = s1.size();
        if (s1 == s2) return true;

        vector<int> memo(n * n * (n + 1), -1);

        function<bool(int, int, int)> solve = [&](int i, int j, int len) -> bool {
            int& result = memo[(i * n + j) * (n + 1) + len];
            if (result != -1) return result;

            if (s1.compare(i, len, s2, j, len) == 0)
                return result = 1;

            int count[26] = {};
            for (int k = 0; k < len; ++k) {
                ++count[s1[i + k] - 'a'];
                --count[s2[j + k] - 'a'];
            }
            for (int value : count) {
                if (value != 0) return result = 0;
            }

            for (int split = 1; split < len; ++split) {
                if (solve(i, j, split) &&
                    solve(i + split, j + split, len - split))
                    return result = 1;

                if (solve(i, j + len - split, split) &&
                    solve(i + split, j, len - split))
                    return result = 1;
            }

            return result = 0;
        };

        return solve(0, 0, n);
    }
};
