        result.reserve(nums.size() - k + 1);

        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            if (lower.empty() || nums[i] <= *lower.rbegin()) {
                lower.insert(nums[i]);
            } else {
                upper.insert(nums[i]);
            }

            if (i >= k) {
                auto it = lower.find(nums[i - k]);
                if (it != lower.end()) {
                    lower.erase(it);
                } else {
                    upper.erase(upper.find(nums[i - k]));
                }
            }

            while (lower.size() > upper.size() + 1) {
                auto it = prev(lower.end());
                upper.insert(*it);
                lower.erase(it);
