#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total % k != 0) return false;

        int target = total / k;
        if (*max_element(nums.begin(), nums.end()) > target) return false;

        int n = nums.size();
        int states = 1 << n;
        vector<int> dp(states, -1);
        dp[0] = 0;

        for (int mask = 0; mask < states; ++mask) {
            if (dp[mask] == -1) continue;

            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;

                int nextMask = mask | (1 << i);
                if (dp[nextMask] != -1) continue;

                int sum = dp[mask] + nums[i];
                if (sum <= target) {
                    dp[nextMask] = sum % target;
                }
            }
        }

        return dp[states - 1] == 0;
    }
};
