class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long low = 0, high = 0;
        for (int num : nums) {
            if (num > low) low = num;
            high += num;
        }

        while (low < high) {
            long long mid = low + (high - low) / 2;
            long long currentSum = 0;
            int parts = 1;

            for (int num : nums) {
                if (currentSum + num > mid) {
                    ++parts;
                    currentSum = num;
                } else {
