#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        vector<array<int, 26>> counts;
        array<int, 26> available{};

        for (const string& sticker : stickers) {
            array<int, 26> count{};
            for (char c : sticker) {
                ++count[c - 'a'];
                available[c - 'a'] = 1;
            }
            counts.push_back(count);
        }

        for (char c : target) {
            if (!available[c - 'a']) return -1;
        }

        int m = target.size();
        int full = (1 << m) - 1;
        vector<int> memo(1 << m, -2);
        memo[full] = 0;

        function<int(int)> solve = [&](int mask) -> int {
            int& answer = memo[mask];
            if (answer != -2) return answer;

            int first = 0;
            while (mask & (1 << first)) ++first;

            int best = INT_MAX;
            for (const auto& count : counts) {
                // Some sticker must supply the first uncovered letter.
                if (count[target[first] - 'a'] == 0) continue;

                auto remaining = count;
                int nextMask = mask;

                for (int i = 0; i < m; ++i) {
                    int letter = target[i] - 'a';
                    if (!(nextMask & (1 << i)) && remaining[letter] > 0) {
                        --remaining[letter];
                        nextMask |= 1 << i;
                    }
                }

                int result = solve(nextMask);
                if (result != -1) best = min(best, result + 1);
            }

            return answer = (best == INT_MAX ? -1 : best);
        };

        return solve(0);
    }
};
