#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int regions = 4 * n * n;
        vector<int> parent(regions), size(regions, 1);
        iota(parent.begin(), parent.end(), 0);

        auto find = [&](int x) {
            while (x != parent[x]) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (size[a] < size[b]) swap(a, b);
            parent[b] = a;
            size[a] += size[b];
            --regions;
        };

        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                // Each cell has four triangles: top, right, bottom, left.
                int base = 4 * (r * n + c);

                if (grid[r][c] != '/') {
                    unite(base, base + 1);
                    unite(base + 2, base + 3);
                }
                if (grid[r][c] != '\\') {
                    unite(base, base + 3);
                    unite(base + 1, base + 2);
                }

                if (r + 1 < n)
                    unite(base + 2, base + 4 * n);
                if (c + 1 < n)
                    unite(base + 1, base + 7);
            }
        }

        return regions;
    }
};
