    vector<Node> trie;
    deque<char> stream;
    size_t maxLength = 0;

public:
    StreamChecker(vector<string>& words) {
        trie.emplace_back();

        for (const string& word : words) {
            maxLength = max(maxLength, word.size());
            int node = 0;

            for (auto it = word.rbegin(); it != word.rend(); ++it) {
                int c = *it - 'a';
                if (trie[node].next[c] == -1) {
                    int child = static_cast<int>(trie.size());
                    trie[node].next[c] = child;
                    trie.emplace_back();
                }
                node = trie[node].next[c];
            }

            trie[node].terminal = true;
        }
    }

    bool query(char letter) {
        stream.push_front(letter);
        if (stream.size() > maxLength) {
            stream.pop_back();
        }

        int node = 0;
        for (char c : stream) {
            node = trie[node].next[c - 'a'];
            if (node == -1) {
                return false;
            }
            if (trie[node].terminal) {
                return true;
            }
        }

        return false;
    }
};
