class Solution {
    pair<int, int> memo[29][29][29]{};

    pair<int, int> solve(int n, int a, int b) {
        if (a + b == n + 1) {
            return {1, 1};
        }

        auto& result = memo[n][a][b];
        if (result.first != 0) {
            return result;
        }

        // Track how many winners stand before each special player.
        bool reachable[29][29]{};
        reachable[0][0] = true;
        int processed = 0;

        for (int left = 1, right = n; left <= right; ++left, --right) {
            int winners[2];
            int count = 0;

            if (left == a || right == a) {
                winners[count++] = a;
            } else if (left == b || right == b) {
                winners[count++] = b;
            } else {
                winners[count++] = left;
                if (left != right) {
                    winners[count++] = right;
                }
            }

            bool next[29][29]{};
            for (int x = 0; x <= processed; ++x) {
                for (int y = x; y <= processed; ++y) {
                    if (!reachable[x][y]) {
                        continue;
                    }

                    for (int k = 0; k < count; ++k) {
                        int winner = winners[k];
                        next[x + (winner < a)][y + (winner < b)] = true;
                    }
                }
            }

            memcpy(reachable, next, sizeof(reachable));
            ++processed;
        }

        int nextN = (n + 1) / 2;
        int earliest = INT_MAX;
        int latest = 0;

        for (int x = 0; x < nextN; ++x) {
            for (int y = x + 1; y < nextN; ++y) {
                if (!reachable[x][y]) {
                    continue;
                }

                auto rounds = solve(nextN, x + 1, y + 1);
                earliest = min(earliest, rounds.first + 1);
                latest = max(latest, rounds.second + 1);
            }
        }

        return result = {earliest, latest};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        auto result = solve(n, firstPlayer, secondPlayer);
        return {result.first, result.second};
    }
};
