#include <vector>
using namespace std;

class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        int digit[26];
        fill(digit, digit + 26, -1);

        bool leading[26] = {};
        for (const string& word : words) {
            if (word.size() > result.size()) return false;
            if (word.size() > 1) leading[word.front() - 'A'] = true;
        }
        if (result.size() > 1) leading[result.front() - 'A'] = true;

        int used = 0;
        int n = static_cast<int>(words.size());
        int columns = static_cast<int>(result.size());

        // Process columns from right to left, accumulating digits and carry.
        auto dfs = [&](auto&& self, int col, int row, int sum) -> bool {
            if (col == columns) return sum == 0;

            if (row < n) {
                const string& word = words[row];
                if (col >= static_cast<int>(word.size())) {
                    return self(self, col, row + 1, sum);
                }

                int ch = word[word.size() - 1 - col] - 'A';
                if (digit[ch] != -1) {
                    return self(self, col, row + 1, sum + digit[ch]);
                }

                for (int d = 0; d <= 9; ++d) {
                    if ((used & (1 << d)) || (d == 0 && leading[ch])) {
                        continue;
                    }

                    digit[ch] = d;
                    used |= 1 << d;
                    bool solved = self(self, col, row + 1, sum + d);
                    used &= ~(1 << d);
                    digit[ch] = -1;

                    if (solved) return true;
                }
                return false;
            }

            // The result digit is forced by the current column sum.
            int ch = result[columns - 1 - col] - 'A';
            int d = sum % 10;
            int carry = sum / 10;

            if (digit[ch] != -1) {
                return digit[ch] == d &&
                       self(self, col + 1, 0, carry);
            }

            if ((used & (1 << d)) || (d == 0 && leading[ch])) {
                return false;
            }

            digit[ch] = d;
            used |= 1 << d;
            bool solved = self(self, col + 1, 0, carry);
            used &= ~(1 << d);
            digit[ch] = -1;
            return solved;
        };

        return dfs(dfs, 0, 0, 0);
    }
};
