class Solution {
public:
    bool isMatch(string s, string p) {
        int m = p.size();
        vector<char> dp(m + 1, false);
        dp[0] = true;

        for (int j = 1; j <= m; ++j) {
            dp[j] = dp[j - 1] && p[j - 1] == '*';
        }

        for (char c : s) {
            bool diagonal = dp[0];
            dp[0] = false;

            for (int j = 1; j <= m; ++j) {
                bool previous = dp[j];

                if (p[j - 1] == '*') {
                    dp[j] = dp[j] || dp[j - 1];
                } else {
                    dp[j] = diagonal &&
                            (p[j - 1] == '?' || p[j - 1] == c);
                }

                diagonal = previous;
            }
        }

        return dp[m];
    }
};
