class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> indegree(n, 0);

        for (int i = 0; i < n; ++i) {
            if (leftChild[i] != -1 && ++indegree[leftChild[i]] > 1)
                return false;
            if (rightChild[i] != -1 && ++indegree[rightChild[i]] > 1)
                return false;
        }

        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) {
                if (root != -1)
                    return false;
                root = i;
            }
        }

        if (root == -1)
            return false;

        vector<bool> visited(n, false);
        vector<int> stack{root};
        int count = 0;

        while (!stack.empty()) {
            int node = stack.back();
            stack.pop_back();

            if (visited[node])
                return false;

            visited[node] = true;
            ++count;

            if (leftChild[node] != -1)
                stack.push_back(leftChild[node]);
            if (rightChild[node] != -1)
                stack.push_back(rightChild[node]);
        }

        return count == n;
    }
};
